{
  "name": "Keithley 6220精密恒流源",
  "name_en": "Keithley 6220 Precision Current Source",
  "manufacturer": "Keithley",
  "description": "Keithley 6220是一款单通道精密恒流源，用于输出稳定、可控的恒定电流。它适合器件电学表征、低电流偏置、材料测试和传感器测量等实验场景，主要用于电流激励而非传统多功能电源输出。",
  "description_en": "The Keithley 6220 is a single-channel precision current source designed to deliver stable, controllable constant current. It is used in laboratory applications such as electrical characterization, low-current biasing, materials testing, and sensor measurements, where current excitation is needed rather than a general-purpose power supply output.",
  "tag_hints": [
    "precision current source",
    "constant current supply",
    "low-current biasing",
    "electrical characterization",
    "SCPI instrument",
    "single-channel source"
  ],
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取或设置输出电流",
      "description_en": "Get or set the output current"
    },
    {
      "action_name": "auto-disable",
      "description": "将输出电流设为零并关闭输出",
      "description_en": "Set the output current to zero and disable the output"
    },
    {
      "action_name": "auto-voltage",
      "description": "获取或设置输出电压属性（该型号不支持）",
      "description_en": "Get or set the output voltage property (not supported on this model)"
    },
    {
      "action_name": "auto-channel",
      "description": "获取可用通道（单通道）",
      "description_en": "Get the available channel (single channel)"
    }
  ]
}

